function lang(){const l=(document.documentElement.lang||'fr').slice(0,2).toLowerCase();return M[l]?l:'fr'}
function ensurePayment(){let s=document.getElementById('dossierPayment');const box=document.querySelector('section.box');if(!box)return null;if(!s){const style=document.createElement('style');style.textContent='#dossierPayment{margin-top:14px;padding:18px;border:2px solid #f6c45388;border-radius:24px;background:linear-gradient(145deg,#f6c45314,#2dd4bf0d,#ffffff07);box-shadow:0 18px 44px #0004}#dossierPayment .pay-k{font-size:11px;font-weight:1000;letter-spacing:.08em;color:#ffe9a8}#dossierPayment h2{margin:7px 0 8px;font-size:24px}#dossierPayment p{margin:0;color:#c5d3cc;font-weight:800;line-height:1.5}#dossierPayment .pay-state{margin-top:12px;padding:12px;border:1px solid #2dd4bf66;border-radius:15px;background:#2dd4bf0d;color:#d5fff8;font-size:12px;font-weight:1000;line-height:1.4}#dossierPayment .pay-methods{margin-top:9px;color:#d5fff8;font-size:11px;font-weight:850;line-height:1.5}#dossierPayment .pay-direct{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:12px}#dossierPayment .pay-direct article{padding:14px;border:1px solid #ffffff24;border-radius:16px;background:#ffffff08;display:grid;gap:6px}#dossierPayment .pay-direct strong{color:#fff3cf;font-size:12px}#dossierPayment .pay-direct span{font-weight:1000}#dossierPayment .pay-direct a{color:#d5fff8;font-weight:1000;text-decoration:none}@media(max-width:640px){#dossierPayment .pay-direct{grid-template-columns:1fr}}';document.head.appendChild(style);s=document.createElement('section');s.id='dossierPayment';s.innerHTML='<div class="pay-k" id="dpK"></div><h2 id="dpH"></h2><p id="dpL"></p><div class="pay-state" id="dpS"></div><div class="pay-methods" id="dpM"></div><div class="pay-direct"><article><strong>🇸🇳 WAVE · SÉNÉGAL</strong><span>JB Beauville</span><a href="tel:+221771342889">+221 77 134 28 89</a></article><article><strong>🇫🇷 SENDWAVE → WAVE SÉNÉGAL</strong><span>Jean Baptiste Beauville</span><a href="tel:+221771342889">+221 77 134 28 89</a></article></div>';box.insertAdjacentElement('afterend',s)}return s}
function apply(){const d=M[lang()],ey=document.getElementById('ey'),pt=document.getElementById('proofTitle'),pl=document.getElementById('proofLabel'),ph=document.getElementById('proofHelp'),btn=document.getElementById('submit'),st=document.getElementById('status');if(ey)ey.textContent=d.ey;if(pt)pt.textContent=d.pay;if(pl)pl.textContent=d.payText;if(ph)ph.textContent='';if(btn&&btn.style.display!=='none')btn.textContent=d.send;if(st&&!st.classList.contains('bad')){if(st.classList.contains('ok')){if(st.textContent!==d.done)st.textContent=d.done}else if(!/Envoi|Sending|Envío|Envio|Invio|Senden|Verzenden|إرسال/i.test(st.textContent)){if(st.textContent!==d.ready)st.textContent=d.ready}}ensurePayment();const k=document.getElementById('dpK'),h=document.getElementById('dpH'),l=document.getElementById('dpL'),s=document.getElementById('dpS'),m=document.getElementById('dpM');if(k)k.textContent=d.title;if(h)h.textContent=d.head;if(l)l.textContent=d.lead;if(s)s.textContent=d.state;if(m)m.textContent=d.methods}
apply();new MutationObserver(apply).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});document.querySelectorAll('#langs button').forEach(b=>b.addEventListener('click',()=>setTimeout(apply,0)));const st=document.getElementById('status');if(st)new MutationObserver(()=>{const d=M[lang()];if(st.classList.contains('bad'))return;if(st.classList.contains('ok')){if(st.textContent!==d.done)st.textContent=d.done}else if(!/Envoi|Sending|Envío|Envio|Invio|Senden|Verzenden|إرسال/i.test(st.textContent)&&st.textContent!==d.ready){st.textContent=d.ready}}).observe(st,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['class']});
